import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { NextResponse } from 'next/server';
import logger from '@/lib/logger.js';

const SPEC_PATH = path.join(process.cwd(), 'docs', 'swagger.json');

// GET /api/docs — serves the OpenAPI spec generated by
// scripts/generateSwagger.js (docs/swagger.json), for any external Swagger
// UI/Postman/codegen tool to consume directly. The human-readable rendered
// version lives at /api-docs.
/**
 * @swagger
 * /api/docs:
 *   get:
 *     tags: [Health]
 *     summary: Raw OpenAPI spec (JSON)
 *     description: Serves the generated docs/swagger.json unchanged, for external tools (Postman, codegen, another Swagger UI instance) to consume. Run `npm run swagger` to regenerate it; it also regenerates automatically via the `prebuild` script.
 *     security: []
 *     responses:
 *       200:
 *         description: The OpenAPI 3 document
 *       503:
 *         description: docs/swagger.json has not been generated yet — run `npm run swagger`
 *         content:
 *           application/json:
 *             schema: { $ref: '#/components/schemas/ErrorResponse' }
 */
export async function GET() {
  try {
    const raw = await readFile(SPEC_PATH, 'utf-8');
    return new NextResponse(raw, { headers: { 'content-type': 'application/json' } });
  } catch (error) {
    logger.error('Failed to read generated OpenAPI spec', { error: error.message });
    return NextResponse.json(
      { message: 'API docs have not been generated yet — run `npm run swagger`.' },
      { status: 503 }
    );
  }
}
